// a library study-desk listing route (different domain)
import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function GET(req: NextRequest) {
  const q = req.nextUrl.searchParams.get('q')?.toLowerCase() ?? ''
  const minSeats = Number(req.nextUrl.searchParams.get('minSeats') ?? 0)
  const where: { name?: { contains: string } } = {}
  if (q) where.name = { contains: q }
  let rows = await db.desk.findMany({ where, orderBy: { name: 'asc' } })
  if (minSeats > 0) rows = rows.filter((d) => d.seats >= minSeats)
  return NextResponse.json({ desks: rows, total: rows.length })
}


